// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address sender, uint256 amount) public {
        vm.assume(sender != c.owner());
        vm.assume(amount > 0);
        vm.deal(sender, amount);
        vm.prank(sender);
        bool ok = true;
        try c.sendMoney(address(0), amount) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
